"use strict";(self.webpackChunkuxcam=self.webpackChunkuxcam||[]).push([[3321],{66140:function(e,a,t){t.r(a),t.d(a,{Head:function(){return c},default:function(){return l}});var s=t(96540),n=t(86997),i=t(54727);var r={seo:{title:"UXCam Case study | Bazaar",description:"UXCam is an analytics solution for mobile apps, web apps and websites. Session Replay, Heatmaps, Funnel Analytics and Quantitative Analytics make UXCam a complete enterprise analytics solution for deeply understanding user behavior.",image:"https://images.ctfassets.net/vv1yxl437u7d/3Mn0AbpUmb4aFxUXNgpzY6/77b23638bee2a4c3cc29e6336ace2e1f/metaimageNEW.png"},hero:{industry:"Ecommerce",title:"How Bazaar <span>Increased Checkout Conversions by 4%</span>",description:"Bazaar Technologies is Pakistan's leading e-commerce platform, connecting households and businesses to essential products across more than ten major cities.",featuresUsed:[{label:"Session Replay",url:"/experience-analytics/session-replay"},{label:"Funnel Analytics",url:"/product-analytics/funnels"}],image:"/assets/images/case-study-bazaar.webp"},stats:[{value:"> 2M installs",label:"on Google Play Store"},{value:"18% increase",label:"in items added to cart after a search"},{value:"4%",label:"checkout conversion lift"}],challenge:{title:"The Challenge",backgroundImage:"https://images.ctfassets.net/vv1yxl437u7d/1Ov4GcUZwhwz6Gdk7x9TIS/ad9823ae58f2e2026f64d865f820a987/Vector.svg",paragraphs:['The Bazaar team faced blind spots in understanding real user behavior. While they used databases for quantitative insights, they lacked visibility into the "why" behind user actions: rage taps, hesitation, and confusing interactions that didn\'t show up in dashboards.'],quote:{text:"We had blind spots with respect to key aspects of user experience like rage taps and general confusion. We also weren't able to capture a full session journey through funnels and flows.",author:"Maida Khan",role:"Senior Product Manager",image:"https://images.ctfassets.net/vv1yxl437u7d/4is4FKArgzXOVqt55LEV6z/c8a389f21dcbe92ca49c87b50c0d85fe/Maida_Khan.webp"}},solution:{title:"The Solution",backgroundImage:"https://images.ctfassets.net/vv1yxl437u7d/28xui9UzDyaFzt7EfaJuio/74b1070ae5cc420b5ac71c1dee040858/Vector.svg",paragraphs:['Bazaar\'s Product Discovery and AI squad implemented UXCam to complement their quantitative stack. The team integrated UXCam easily, describing the setup as "straightforward", and began analyzing the app through <a href="/experience-analytics/session-replay">session replays</a> and funnel visualization.',"Session replays allowed the product and design teams to observe real user behavior, identify UI pain points, and validate hypotheses before running experiments.","The team focused on their multi-search feature, where session replays revealed UI design challenges that confused users, issues that quantitative data alone couldn't explain."],quote:{text:"UXCam helped us move faster from assumptions to evidence.",author:"Maida Khan",role:"Senior Product Manager",image:"https://images.ctfassets.net/vv1yxl437u7d/4is4FKArgzXOVqt55LEV6z/c8a389f21dcbe92ca49c87b50c0d85fe/Maida_Khan.webp"}},whatsNext:{title:"The Result",backgroundImage:"https://images.ctfassets.net/vv1yxl437u7d/Bc9n79vDsJLoV0HUy6g4j/db1b14e3e0162ced77ac4f4e7f6b5e6a/Path-7.svg",paragraphs:["Through these insights, the team uncovered key findings and took action:<ul><li>Only 29% of users who reached the search landing page actually initiated a search</li><li>Session replays revealed UI design challenges that confused users, issues that quantitative data couldn't explain</li><li>The team ran an A/B test informed by these insights, resulting in an 18% increase in items added to cart and a 4% lift in checkout conversion rate</li></ul>","With faster visibility into friction points, Bazaar's product team now makes decisions grounded in evidence, boosting confidence and collaboration across squads."],quote:{text:"UXCam made the decisions far more evidence-based and increased user empathy.",author:"Maida Khan",role:"Senior Product Manager",image:"https://images.ctfassets.net/vv1yxl437u7d/4is4FKArgzXOVqt55LEV6z/c8a389f21dcbe92ca49c87b50c0d85fe/Maida_Khan.webp"}}},o=t(17437);const c=()=>(0,o.Y)(s.Fragment,null,(0,o.Y)(i.A,{title:r.seo.title,description:r.seo.description,image:{file:{url:r.seo.image}}}),(0,o.Y)("link",{rel:"canonical",href:"https://uxcam.com/case-study/bazaar/"}),(0,o.Y)("link",{rel:"alternate",hrefLang:"en",href:"https://uxcam.com/case-study/bazaar/"}),(0,o.Y)("link",{rel:"alternate",hrefLang:"es",href:"https://uxcam.com/es/case-study/bazaar/"}),(0,o.Y)("link",{rel:"alternate",hrefLang:"pt-BR",href:"https://uxcam.com/br/case-study/bazaar/"}),(0,o.Y)("link",{rel:"alternate",hrefLang:"x-default",href:"https://uxcam.com/case-study/bazaar/"}));var l=()=>(0,o.Y)(n.A,{data:r})}}]);